import React, { useState, useEffect } from 'react';
import { Search, MapPin, Star, Filter, ArrowLeft, SlidersHorizontal, Menu, X } from 'lucide-react';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '../../components/ui/card';
import { Badge } from '../../components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../../components/ui/select';
import { Checkbox } from '../../components/ui/checkbox';
import { serviceCategories } from '../../data/mockData';
import { useNavigate, useLocation } from 'react-router-dom';
import apiService from '../../services/api';
import QuotationRequestForm from '../../components/QuotationRequestForm';

const ServiceBrowse = () => {
  console.log('ServiceBrowse component rendering');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedServices, setSelectedServices] = useState([]);
  const [sortBy, setSortBy] = useState('rating');
  const [showFilters, setShowFilters] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [allProviders, setAllProviders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showQuotationForm, setShowQuotationForm] = useState(false);
  const [selectedProvider, setSelectedProvider] = useState(null);
  const navigate = useNavigate();
  const location = useLocation();

  console.log('ServiceBrowse state:', { allProviders, loading, error });


  // Scroll to top when component mounts
  useEffect(() => {
    console.log('ServiceBrowse useEffect triggered');
    window.scrollTo(0, 0);
    
    // Check if user is logged in
    const userType = localStorage.getItem('userType');
    const authToken = localStorage.getItem('authToken');
    const user = localStorage.getItem('user');
    
    // User is logged in if they have a token and user data
    const userIsLoggedIn = !!(authToken && user);
    setIsLoggedIn(userIsLoggedIn);
    
    // If user is logged in but not a homeowner, they can still browse but buttons will redirect appropriately
    console.log('User logged in:', userIsLoggedIn, 'User type:', userType);
    
    // Get selected service from URL params
    const searchParams = new URLSearchParams(location.search);
    const serviceParam = searchParams.get('service');
    console.log('Service parameter from URL:', serviceParam);
    if (serviceParam) {
      setSelectedServices([serviceParam]);
      console.log('Set selected services to:', [serviceParam]);
    }
    
    // Load providers from API
    console.log('About to call loadProviders');
    loadProviders();
  }, [location]);

  // Load providers from API
  const loadProviders = async () => {
    try {
      setLoading(true);
      setError('');
      
      // Add cache-busting parameter
      const providers = await apiService.getAllProviders();
      console.log('Loaded providers from API:', providers);
      
      // Format providers for display
      const formattedProviders = providers.map(provider => ({
        id: provider.id,
        name: provider.business_name || provider.name,
        business_name: provider.business_name,
        ownerName: provider.name,
        description: provider.description || `Professional ${Array.isArray(provider.services) && provider.services.length > 0 ? provider.services.join(' and ') : 'service'} services`,
        services: Array.isArray(provider.services) && provider.services.length > 0 ? provider.services : ['General Services'],
        rating: provider.rating || 5.0,
        reviews: provider.reviews || 0,
        completedJobs: provider.completed_jobs || 0,
        location: provider.location || "Halifax, NS",
        responseTime: provider.response_time || "Usually responds within 1 hour",
        yearEstablished: provider.year_established || "2024",
        specialties: provider.specialties || ["Professional service", "Quality work", "Customer satisfaction"],
        priceRange: provider.price_range || "$50-$500",
        email: provider.email,
        phone: provider.phone
      }));
      
      console.log('Formatted providers:', formattedProviders);
      setAllProviders(formattedProviders);
    } catch (error) {
      console.error('Failed to load providers:', error);
      setError('Failed to load service providers. Please try again.');
      setAllProviders([]);
    } finally {
      setLoading(false);
    }
  };


  const filteredProviders = allProviders
    .filter(provider => {
      try {
        // Hide Wilson Home Services entries - comprehensive filtering
        const providerName = (provider.name || '').toLowerCase();
        const businessName = (provider.business_name || '').toLowerCase();
        const companyName = (provider.companyName || '').toLowerCase();
        
        if (providerName.includes('wilson') || 
            businessName.includes('wilson') || 
            companyName.includes('wilson') ||
            providerName.includes('wilson home services') ||
            businessName.includes('wilson home services') ||
            companyName.includes('wilson home services')) {
          return false;
        }
        
        // Ensure services is an array
        const providerServices = Array.isArray(provider.services) ? provider.services : [];
        
        const matchesSearch = !searchTerm || 
          provider.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          providerServices.some(service => 
            service.toLowerCase().includes(searchTerm.toLowerCase())
          );
        
        const matchesServices = selectedServices.length === 0 ||
          selectedServices.some(service => {
          console.log(`Filtering by service: ${service}`);
          // Strict matching for service categories - no cross-contamination
          return providerServices.some(providerService => {
            const providerServiceLower = providerService.toLowerCase().trim();
            const serviceLower = service.toLowerCase().trim();
            
            console.log(`Checking provider service "${providerServiceLower}" against filter "${serviceLower}"`);
            
            // Direct exact match first
            if (providerServiceLower === serviceLower) {
              console.log('Direct exact match found');
              return true;
            }
            
            // Handle specific service name variations with strict mapping
            const serviceMapping = {
              // Electrical services - ONLY electrical related
              'electrician': ['electrical', 'electrician', 'electrical work', 'electrical services', 'electrical repair'],
              'electrical': ['electrical', 'electrician', 'electrical work', 'electrical services', 'electrical repair'],
              'electrical services': ['electrical', 'electrician', 'electrical work', 'electrical services', 'electrical repair'],
              
              // Plumbing services - ONLY plumbing related
              'plumber': ['plumbing', 'plumber', 'plumbing services', 'plumbing repair', 'pipe repair'],
              'plumbing': ['plumbing', 'plumber', 'plumbing services', 'plumbing repair', 'pipe repair'],
              'plumbing services': ['plumbing', 'plumber', 'plumbing services', 'plumbing repair', 'pipe repair'],
              
              // Cleaning services - separated by type
              'home cleaning': ['home cleaning', 'house cleaning', 'residential cleaning'],
              'office cleaning': ['office cleaning', 'commercial cleaning', 'business cleaning'],
              'window cleaning': ['window cleaning', 'window wash', 'window washing'],
              'pressure washing': ['pressure washing', 'power washing', 'exterior cleaning'],
              'gutter cleaning': ['gutter cleaning', 'gutter services', 'gutter maintenance'],
              
              // Other services - specific only
              'handyman': ['handyman', 'handyman services', 'general repairs', 'home repairs'],
              'handyman services': ['handyman', 'handyman services', 'general repairs', 'home repairs'],
              'landscaping': ['landscaping', 'lawn care', 'garden services', 'yard work', 'outdoor maintenance'],
              'lawn mowing & maintenance': ['landscaping', 'lawn care', 'garden services', 'yard work', 'lawn mowing'],
              'painter': ['painting', 'painter', 'paint services', 'interior painting', 'exterior painting'],
              'hvac services': ['hvac', 'heating', 'cooling', 'air conditioning', 'hvac services'],
              'carpenter': ['carpentry', 'carpenter', 'woodwork', 'wood services'],
              'roofing': ['roofing', 'roof repair', 'roof services', 'roof installation'],
              'pest control': ['pest control', 'extermination', 'pest services', 'pest removal'],
              'appliance repair': ['appliance repair', 'appliance services', 'appliance fix'],
              'junk removal': ['junk removal', 'waste removal', 'cleanup', 'debris removal'],
              'car detailing': ['car detailing', 'auto detailing', 'car wash', 'vehicle cleaning'],
              'snow removal': ['snow removal', 'snow services', 'winter services', 'snow clearing'],
              'fence & deck services': ['fence', 'deck', 'fencing', 'deck services', 'fence installation'],
              'siding installation & repair': ['siding', 'siding installation', 'siding repair', 'exterior siding']
            };
            
            // Get the mapped services for the filter
            const mappedServices = serviceMapping[serviceLower] || [serviceLower];
            
            // Check if provider service matches any of the mapped services
            const matches = mappedServices.some(mapped => {
              const mappedLower = mapped.toLowerCase().trim();
              // Strict matching - either exact match or provider service contains the mapped service
              return providerServiceLower === mappedLower || 
                     providerServiceLower.includes(mappedLower);
            });
            
            if (matches) {
              console.log(`Strict match found: ${providerServiceLower} matches ${serviceLower}`);
            }
            
            return matches;
          });
        });
      
        console.log(`Provider ${provider.name}: matchesSearch=${matchesSearch}, matchesServices=${matchesServices}, selectedServices=${selectedServices.join(', ')}`);
      
        return matchesSearch && matchesServices;
      } catch (error) {
        console.error('Error filtering provider:', provider, error);
        return false; // Exclude providers that cause errors
      }
    });

  console.log('Filtered providers:', filteredProviders);

  const sortedProviders = [...filteredProviders].sort((a, b) => {
    switch (sortBy) {
      case 'rating':
        return b.rating - a.rating;
      case 'reviews':
        return b.reviews - a.reviews;
      case 'name':
        return a.name.localeCompare(b.name);
      default:
        return 0;
    }
  });

  const handleServiceToggle = (serviceName) => {
    setSelectedServices(prev => 
      prev.includes(serviceName)
        ? prev.filter(s => s !== serviceName)
        : [...prev, serviceName]
    );
  };

  const handleGetQuotation = (providerId) => {
    // Check if user is logged in
    const authToken = localStorage.getItem('authToken');
    const user = localStorage.getItem('user');
    const userType = localStorage.getItem('userType');
    
    if (!authToken || !user) {
      navigate('/homeowners/auth');
      return;
    }
    
    // If user is a provider, redirect to provider dashboard
    if (userType === 'provider') {
      navigate('/homeservices/dashboard');
      return;
    }
    
    // Find the provider and show quotation form
    const provider = allProviders.find(p => p.id === providerId);
    if (provider) {
      setSelectedProvider(provider);
      setShowQuotationForm(true);
    }
  };

  const handleRequestQuote = (providerId) => {
    // Same as get quotation - show the form
    handleGetQuotation(providerId);
  };

  const handleGetBestDeal = async (providerId) => {
    // Check if user is logged in
    const authToken = localStorage.getItem('authToken');
    const user = localStorage.getItem('user');
    const userType = localStorage.getItem('userType');
    
    if (!authToken || !user || userType !== 'homeowner') {
      navigate('/homeowners/auth');
      return;
    }
    
    try {
      // Get fresh provider details from API
      const provider = await apiService.getProviderById(providerId);
      if (!provider) {
        console.error('Provider not found');
        alert('Provider not found. Please try again.');
        return;
      }
      
      const userData = JSON.parse(user);
      
      // Check if conversation already exists
      const existingThreads = await apiService.getMessageThreads();
      const existingThread = existingThreads.find(thread => 
        thread.provider_id === providerId && thread.homeowner_id === userData.id
      );
      
      if (existingThread) {
        // Navigate to existing conversation
        navigate('/homeowners/dashboard?tab=messages', { 
          state: { 
            threadId: existingThread.id,
            providerId: providerId,
            providerName: provider.business_name || provider.name,
            action: 'openExistingConversation'
          }
        });
        return;
      }
      
      // Create new conversation thread
      const threadData = {
        homeowner_id: userData.id,
        provider_id: providerId,
        homeowner_name: userData.name,
        provider_name: provider.business_name || provider.name,
        order_type: 'Text Us Inquiry',
        last_message: `New conversation with ${provider.name}`,
        last_message_time: new Date().toISOString()
      };
      
      const newThread = await apiService.createMessageThread(threadData);
      
      // Navigate to messages with the new thread
      navigate('/homeowners/dashboard?tab=messages', { 
        state: { 
          threadId: newThread.id,
          providerId: providerId,
          providerName: provider.business_name || provider.name,
          action: 'newConversation'
        }
      });
      
    } catch (error) {
      console.error('Failed to start conversation:', error);
      alert('Failed to start conversation. Please try again.');
    }
  };

  const handleQuotationFormClose = () => {
    setShowQuotationForm(false);
    setSelectedProvider(null);
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <Button 
                variant="ghost" 
                onClick={() => navigate(-1)}
                className="p-2"
              >
                <ArrowLeft className="h-5 w-5" />
              </Button>
              <h1 className="text-xl sm:text-2xl font-bold text-blue-600">Doord.</h1>
            </div>
            
            {/* Desktop Navigation */}
            <div className="hidden md:flex items-center space-x-4">
              <Button 
                variant="ghost" 
                onClick={() => navigate('/homeowners/dashboard')}
              >
                Explore
              </Button>
              {isLoggedIn ? (
                <Button variant="outline" onClick={() => {
                  localStorage.removeItem('userType');
                  localStorage.removeItem('user');
                  setIsLoggedIn(false);
                }}>
                  Sign Out
                </Button>
              ) : (
                <>
                  <Button variant="outline" onClick={() => navigate('/homeowners/auth')}>
                    Sign In
                  </Button>
                  <Button onClick={() => navigate('/homeowners/auth')}>
                    Sign Up
                  </Button>
                </>
              )}
            </div>
            
            {/* Mobile Menu Button */}
            <div className="md:hidden">
              <Button
                variant="ghost"
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="p-2"
              >
                {isMobileMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
              </Button>
            </div>
          </div>
          
          {/* Mobile Menu */}
          {isMobileMenuOpen && (
            <div className="md:hidden border-t bg-white py-4">
              <div className="flex flex-col space-y-3">
                <Button 
                  variant="ghost" 
                  onClick={() => {
                    navigate('/homeowners/dashboard');
                    setIsMobileMenuOpen(false);
                  }}
                  className="justify-start"
                >
                  Explore
                </Button>
                {isLoggedIn ? (
                  <Button 
                    variant="outline" 
                    onClick={() => {
                      localStorage.removeItem('userType');
                      localStorage.removeItem('user');
                      setIsLoggedIn(false);
                      setIsMobileMenuOpen(false);
                    }}
                    className="justify-start"
                  >
                    Sign Out
                  </Button>
                ) : (
                  <>
                    <Button 
                      variant="outline" 
                      onClick={() => {
                        navigate('/homeowners/auth');
                        setIsMobileMenuOpen(false);
                      }}
                      className="justify-start"
                    >
                      Sign In
                    </Button>
                    <Button 
                      onClick={() => {
                        navigate('/homeowners/auth');
                        setIsMobileMenuOpen(false);
                      }}
                      className="justify-start"
                    >
                      Sign Up
                    </Button>
                  </>
                )}
              </div>
            </div>
          )}
        </div>
      </header>

          {/* Search and Filters */}
          <div className="bg-white border-b">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 sm:py-6">
              <div className="flex flex-col gap-4">
                <div className="flex-1">
                  <div className="relative">
                    <Search className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                    <Input
                      placeholder="Search services or providers..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="pl-10 h-12"
                    />
                  </div>
                </div>
                
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center space-y-2 sm:space-y-0 sm:space-x-4">
                  <div className="relative">
                    <Select value={sortBy} onValueChange={setSortBy}>
                      <SelectTrigger className="w-full sm:w-48 bg-white">
                        <SelectValue placeholder="Sort by" />
                      </SelectTrigger>
                      <SelectContent className="z-[9999] bg-white border border-gray-200 shadow-2xl rounded-md min-w-[200px] max-h-[200px] overflow-auto">
                        <SelectItem value="rating" className="hover:bg-gray-50 cursor-pointer px-3 py-2 text-gray-900">Highest Rated</SelectItem>
                        <SelectItem value="reviews" className="hover:bg-gray-50 cursor-pointer px-3 py-2 text-gray-900">Most Reviews</SelectItem>
                        <SelectItem value="name" className="hover:bg-gray-50 cursor-pointer px-3 py-2 text-gray-900">Name A-Z</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  
                  <Button
                    variant="outline"
                    onClick={() => setShowFilters(!showFilters)}
                    className="flex items-center justify-center space-x-2 w-full sm:w-auto bg-white hover:bg-gray-50 border-gray-200"
                  >
                    <SlidersHorizontal className="h-4 w-4" />
                    <span>Filters</span>
                  </Button>
                </div>
                
                {/* Filters Panel */}
                {showFilters && (
                  <div className="mt-4 p-4 border rounded-lg bg-gray-50">
                    <h3 className="font-semibold mb-4">Filter by Services</h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                      {serviceCategories.map(category => (
                        <div key={category.id}>
                          <h4 className="font-medium text-sm text-gray-700 mb-2">{category.name}</h4>
                          <div className="space-y-2">
                            {category.services.map(service => (
                              <div key={service.id} className="flex items-center space-x-2">
                                <Checkbox
                                  id={service.name}
                                  checked={selectedServices.includes(service.name)}
                                  onCheckedChange={() => handleServiceToggle(service.name)}
                                />
                                <label
                                  htmlFor={service.name}
                                  className="text-sm text-gray-600 cursor-pointer"
                                >
                                  {service.name}
                                </label>
                              </div>
                            ))}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

      {/* Results */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-gray-900">
            {selectedServices.length > 0 
              ? `${selectedServices.join(', ')} Services` 
              : 'All Services'
            }
          </h2>
          <p className="text-gray-600">
            {sortedProviders.length} provider{sortedProviders.length !== 1 ? 's' : ''} found
          </p>
        </div>

        {sortedProviders.length === 0 ? (
          <div className="text-center py-12">
            <div className="text-gray-400 text-4xl mb-4">🔍</div>
            <h3 className="text-xl font-semibold text-gray-700 mb-2">
              {selectedServices.length > 0 
                ? `No ${selectedServices.join(', ')} providers found` 
                : 'No providers found matching your criteria'
              }
            </h3>
            <p className="text-gray-600 mb-4">
              {selectedServices.length > 0 
                ? `We couldn't find any providers offering ${selectedServices.join(', ')} services in your area.`
                : 'Try adjusting your search criteria or browse all services.'
              }
            </p>
            <Button 
              variant="outline" 
              onClick={() => {
                setSearchTerm('');
                setSelectedServices([]);
              }}
              className="mt-4"
            >
              Clear Filters
            </Button>
          </div>
        ) : (
          <div className="grid gap-6">
            {sortedProviders.map(provider => (
              <Card 
                key={provider.id} 
                className="hover:shadow-lg transition-shadow cursor-pointer"
                onClick={() => navigate(`/homeowners/provider/${provider.id}`)}
              >
                <CardContent className="p-4 sm:p-6">
                  <div className="flex flex-col gap-4 sm:gap-6">
                    {/* Image Gallery */}
                    <div className="w-full sm:w-80 mx-auto sm:mx-0">
                      <div className="grid grid-cols-4 gap-2 h-32 sm:h-48">
                        <div className="col-span-2 bg-gradient-to-br from-blue-100 to-blue-200 rounded-lg flex items-center justify-center">
                          <div className="text-center">
                            <div className="text-2xl sm:text-3xl mb-1 sm:mb-2">
                              {provider.services.includes('Home Cleaning') || provider.services.includes('Office Cleaning') ? '🧹' :
                               provider.services.includes('Plumber') ? '🔧' :
                               provider.services.includes('Electrician') ? '⚡' :
                               provider.services.includes('Landscaping') ? '🌱' : '🏠'}
                            </div>
                            <p className="text-xs text-gray-600">Professional Services</p>
                          </div>
                        </div>
                        <div className="grid grid-rows-2 gap-2">
                          <div className="bg-gradient-to-br from-green-100 to-green-200 rounded-lg flex items-center justify-center">
                            <div className="text-lg sm:text-xl">✨</div>
                          </div>
                          <div className="bg-gradient-to-br from-orange-100 to-orange-200 rounded-lg flex items-center justify-center">
                            <div className="text-lg sm:text-xl">🏠</div>
                          </div>
                        </div>
                        <div className="grid grid-rows-2 gap-2">
                          <div className="bg-gradient-to-br from-purple-100 to-purple-200 rounded-lg flex items-center justify-center">
                            <div className="text-lg sm:text-xl">💯</div>
                          </div>
                          <div className="bg-gradient-to-br from-yellow-100 to-yellow-200 rounded-lg flex items-center justify-center">
                            <div className="text-lg sm:text-xl">⭐</div>
                          </div>
                        </div>
                      </div>
                    </div>
                    
                    {/* Content */}
                    <div className="flex-1">
                      <div className="flex flex-col sm:flex-row items-start justify-between mb-4">
                        <div className="w-full">
                          <div className="flex flex-col sm:flex-row items-start sm:items-center space-y-2 sm:space-y-0 sm:space-x-3 mb-2">
                            <h3 className="text-lg sm:text-xl font-semibold text-gray-900">
                              {provider.business_name || provider.name}
                            </h3>
                            {provider.business_name && provider.ownerName && (
                              <span className="text-sm text-gray-500">by {provider.ownerName}</span>
                            )}
                            <button className="p-1 hover:bg-gray-100 rounded-full self-start sm:self-auto">
                              <svg className="h-4 w-4 sm:h-5 sm:w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                              </svg>
                            </button>
                          </div>
                          <div className="flex flex-col sm:flex-row items-start sm:items-center space-y-1 sm:space-y-0 sm:space-x-2 mt-1">
                            <div className="bg-blue-600 text-white px-2 py-1 rounded text-sm font-semibold">
                              {provider.rating} ★
                            </div>
                            <span className="text-gray-500 text-sm">({provider.reviews} reviews)</span>
                            <span className="text-gray-300 hidden sm:inline">•</span>
                            <span className="text-gray-600 text-sm">{provider.completedJobs} jobs completed</span>
                          </div>
                        </div>
                      </div>
                      
                      <p className="text-gray-600 mb-4 text-sm sm:text-base">{provider.description}</p>
                      
                      <div className="flex flex-wrap gap-1 sm:gap-2 mb-4">
                        {provider.services.map(service => (
                          <Badge key={service} variant="outline" className="text-xs">{service}</Badge>
                        ))}
                      </div>
                      
                      <div className="flex flex-col sm:flex-row items-start sm:items-center space-y-1 sm:space-y-0 sm:space-x-4 text-xs sm:text-sm text-gray-500 mb-4">
                        <span>📍 {provider.location}</span>
                        <span>⏱️ {provider.responseTime}</span>
                        <span>📅 Est. {provider.yearEstablished}</span>
                      </div>
                      
                      <div className="flex flex-col sm:flex-row space-y-2 sm:space-y-0 sm:space-x-3">
                        <Button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleGetQuotation(provider.id);
                          }}
                          className="w-full sm:flex-1 bg-blue-600 hover:bg-blue-700 text-white"
                        >
                          Get Quotation
                        </Button>
                        <Button
                          variant="outline"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleRequestQuote(provider.id);
                          }}
                          className="w-full sm:w-auto bg-blue-600 text-white hover:bg-blue-700"
                        >
                          Starts from $199.00
                        </Button>
                        <Button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleGetBestDeal(provider.id);
                          }}
                          className="w-full sm:w-auto"
                        >
                          Text Us
                        </Button>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
      
      {/* Quotation Request Form */}
      {showQuotationForm && selectedProvider && (
        <QuotationRequestForm
          isOpen={showQuotationForm}
          onClose={handleQuotationFormClose}
          serviceType={selectedProvider.services[0]}
          providerName={selectedProvider.name}
          providerId={selectedProvider.id}
        />
      )}
    </div>
  );
};

export default ServiceBrowse;